def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    people = image_patch.find("person")
    cars = image_patch.find("car")

    if not people or not cars:
        return image_patch

    people.sort(key=lambda p: p.horizontal_center)
    car_sort = depth_order(cars)

    for person in people:
        person_left = person.left
        person_right = person.right
        person_center = (person.left + person.right) / 2

        for car in car_sort:
            car_left = car.left
            car_right = car.right
            car_center = (car.left + car.right) / 2

            if person_center < car_left:
                continue
            elif person_center >= car_right:
                break
            else:
                return car

    return image_patch

def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    boy_patches = image_patch.find("boy")
    suitcase_patches = image_patch.find("suitcase")
    stripe_patches = image_patch.find("stripe shirt")

    if not boy_patches or not suitcase_patches or not stripe_patches:
        return image_patch

    boy_horizontal_center = sum(p.horizontal_center for p in boy_patches) / len(boy_patches)
    boy_vertical_center = sum(p.vertical_center for p in boy_patches) / len(boy_patches)

    closest_suitcase = min(suitcase_patches, key=lambda s: distance(s, ImagePatch(image, boy_horizontal_center, boy_vertical_center)))
    closest_stripe = min(stripe_patches, key=lambda s: distance(s, ImagePatch(image, boy_horizontal_center, boy_vertical_center)))

    boy_on_suitcase = is_above_or_below(closest_suitcase, boy_patches[0]) and is_in_front_of(boy_patches[0], closest_stripe)

    return boy_patches[0] if boy_on_suitcase else image_patch

def is_above_or_below(a: ImagePatch, b: ImagePatch) -> bool:
    return abs(a.vertical_center - b.vertical_center) < abs(a.horizontal_center - b.horizontal_center)

def distance(patch_a: ImagePatch, patch_b: ImagePatch) -> float:
    return math.sqrt((patch_a.left - patch_b.left)**2 + (patch_a.lower - patch_b.lower)**2)

