def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    skiers = image_patch.find("skier")

    if not skiers:
        return image_patch

    skiers.sort(key=lambda p: p.horizontal_center)
    front_skier = skiers[0]

    depth_sorted_skiers = depth_order(skiers)

    for i, skier in enumerate(depth_sorted_skiers):
        if skier == front_skier:
            if i < len(depth_sorted_skiers) - 1 and is_in_front_of(depth_sorted_skiers[i + 1], skier):
                return depth_sorted_skiers[i + 1]
            elif i > 0 and is_in_front_of(skier, depth_sorted_skiers[i - 1]):
                return depth_sorted_skiers[i - 1]
            return skier

    return front_skier

